def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    # Identify alive opponents
    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive.append((opp_id, opp))

    # If no one is alive, bid conservatively
    if not alive:
        return max(0, min(int(my_status.get('budget', 0)), int(DAILY_SALARY * 0.4)))

    # Read yesterday bids from previous_trace only
    prev_bids = []
    for _, opp in alive:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    # Estimate pressure from yesterday
    # Cindy/Bob were high (~86-91) while Eric bid 0 and died; so use max/median
    pressure_max = max(prev_bids) if prev_bids else 0.0
    pressure_med = 0.0
    if prev_bids:
        s = sorted(prev_bids)
        pressure_med = s[len(s)//2]

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # Supply factor: with supply 15-25 and WATER_REQ=13, at least 1 unit is possible.
    # If supply is near minimum, winning matters more.
    # Convert to an integer count of water units available (at least 1).
    water_units = max(1, int(supply / WATER_REQ))

    # Base bid target
    # - If yesterday pressure was high, bid near the median/high to avoid losing.
    # - If my hp is low or I've already missed water days, bid aggressively.
    if pressure_max >= DAILY_SALARY * 1.25:  # ~87.5+
        base = max(DAILY_SALARY * 0.85, pressure_med + 2.0)
    elif pressure_med >= DAILY_SALARY * 1.05:
        base = max(DAILY_SALARY * 0.75, pressure_med + 1.0)
    else:
        base = DAILY_SALARY * 0.55

    # Adjust for my urgency
    if my_hp <= 2 or no_water_days >= 2:
        base *= 1.25
    elif my_hp <= 4:
        base *= 1.10

    # Adjust for supply scarcity
    if supply <= (MIN_SUPPLY + 1.0):
        base *= 1.10
    elif supply >= (MAX_SUPPLY - 1.0):
        base *= 0.95

    # Cap by budget and keep bids non-negative
    bid = int(max(0, min(my_budget, base)))

    # If budget is tiny, still try to win when hp is critical
    if my_budget < DAILY_SALARY * 0.3:
        if my_hp <= 2:
            return int(max(0, min(my_budget, DAILY_SALARY * 0.9)))
        return int(max(0, min(my_budget, DAILY_SALARY * 0.4)))

    return bid

