        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return float(min(budget, 20.0))

    opp_bids = []
    urgent_opp = False
    max_req = WATER_REQ
    for oid, opp in alive:
        req = opp.get('water_requirement', WATER_REQ)
        if req > max_req:
            max_req = req
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            opp_bids.append(float(prev['bid']))
        if opp.get('no_water_days', 0) >= 2 or opp.get('hp', 10) <= 3:
            urgent_opp = True
        if prev:
            status = prev.get('status')
            if status in ('thirsty', 'critical', 'failed'):
                urgent_opp = True

    units = int(supply / WATER_REQ)
    max_units = int(supply / max_req) if max_req > 0 else units
    contested = units <= 2 or max_units <= 2
    loose = units >= 3 and supply >= 22

    highest_prev = max(opp_bids) if opp_bids else 0.0

    david_like = False
    cindy_like = False
    for oid, opp in alive:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            b = float(bid)
            if 66.0 <= b <= 70.0:
                david_like = True
            if b >= 85.0:
                cindy_like = True

    if hp <= 2 or no_water_days >= 2:
        bid = min(budget, max(82.0, highest_prev + 2.0, DAILY_SALARY * 0.92))
        return float(max(0.0, bid))

    if contested:
        if david_like:
            base = 69.5
        elif highest_prev >= 60.0 and highest_prev < 85.0:
            base = highest_prev + 1.5
        elif highest_prev >= 85.0:
            base = 71.0
        else:
            base = 68.5

        if urgent_opp:
            base += 3.0
        if hp <= 4 or no_water_days >= 1:
            base += 6.0
        bid = min(budget, base)
        return float(max(0.0, bid))

    if loose:
        if hp >= 7 and no_water_days == 0:
            bid = min(budget, 18.0)
        else:
            bid = min(budget, 32.0)
        return float(max(0.0, bid))

    base = 42.0
    if highest_prev > 0.0:
        if highest_prev < 50.0:
            base = highest_prev + 2.0
        elif highest_prev < 75.0:
            base = 55.0
        else:
            base = 48.0

    if cindy_like and hp >= 6 and no_water_days == 0:
        base -= 6.0
    if urgent_opp:
        base += 4.0
    if hp <= 4 or no_water_days >= 1:
        base += 8.0

    bid = min(budget, max(12.0, base))
    return float(max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
